// Package store is the control plane's persistence layer: config versions,
// users, sessions, API tokens, secrets, the audit log and events.
//
// All queries live once in internal/store/queries, are generated by sqlc from
// the PostgreSQL dialect, and run unchanged on PostgreSQL and SQLite (the SQLite
// path rewrites $n placeholders to ?n). The conformance suite in storetest runs
// the same tests on both engines, so a query that only one accepts fails there.
//
// Every operation happens inside a transaction (Store.Tx), which is what lets a
// config commit and its audit row succeed or fail together.
package store

import (
	"context"
	"errors"
	"time"
)

// Errors returned by every implementation.
var (
	// ErrNotFound means the row does not exist.
	ErrNotFound = errors.New("store: not found")
	// ErrConflict means a unique constraint was violated.
	ErrConflict = errors.New("store: conflict")
)

// Dialect names the engine behind a Store.
type Dialect string

// Supported engines.
const (
	SQLite   Dialect = "sqlite"
	Postgres Dialect = "postgres"
)

// Store opens transactions. Implementations are safe for concurrent use.
type Store interface {
	// Tx runs fn in a transaction, committing if it returns nil and rolling
	// back otherwise (including on panic).
	Tx(ctx context.Context, fn func(ctx context.Context, tx Tx) error) error
	Dialect() Dialect
	Ping(ctx context.Context) error
	Close() error
}

// Tx is the set of operations available inside a transaction.
type Tx interface {
	KV
	Config
	Sites
	Secrets
	Users
	Sessions
	Tokens
	Audit
	Events
	Certificates
	BlockPages
	APIAssets
	Bans
}

// KV is small node state (install id, key check value, feature flags).
type KV interface {
	GetKV(ctx context.Context, key string) (string, error)
	SetKV(ctx context.Context, key, value string) error
	DeleteKV(ctx context.Context, key string) error
}

// ConfigVersion is one stored configuration. Snapshot and Diff are JSON text
// stored and returned byte for byte.
type ConfigVersion struct {
	ID            string
	ParentID      string
	CreatedAt     time.Time
	AuthorType    string // user, token, system, cli
	AuthorID      string
	Source        string // api, import, rollback, cli, boot
	SchemaVersion int
	Snapshot      []byte
	Diff          []byte
	Applied       bool
}

// Cursor positions a descending (time, id) listing; the zero value starts at the newest.
type Cursor struct {
	Time time.Time
	ID   string
}

// Config stores versions and the head pointer.
type Config interface {
	// ConfigHead returns the id of the applied version, or "" before the first.
	ConfigHead(ctx context.Context) (string, error)
	// CompareAndSetConfigHead moves the head from expected to next and reports
	// whether it did (false: someone else moved it first).
	CompareAndSetConfigHead(ctx context.Context, expected, next string) (bool, error)
	InsertConfigVersion(ctx context.Context, v ConfigVersion) error
	GetConfigVersion(ctx context.Context, id string) (ConfigVersion, error)
	// ListConfigVersions returns versions older than c, newest first.
	ListConfigVersions(ctx context.Context, c Cursor, limit int) ([]ConfigVersion, error)
}

// Site is the listing projection of a site in the head snapshot.
type Site struct {
	ID        string
	Name      string
	Mode      string
	Hosts     []byte // JSON array
	UpdatedAt time.Time
}

// Sites is the projection of the head snapshot.
type Sites interface {
	ReplaceSites(ctx context.Context, sites []Site) error
	ListSites(ctx context.Context) ([]Site, error)
}

// Secret is an encrypted value; see internal/secrets for the envelope.
type Secret struct {
	ID         string
	Purpose    string
	KeyID      int
	Nonce      []byte
	Ciphertext []byte
	CreatedAt  time.Time
}

// Secrets stores encrypted values.
type Secrets interface {
	InsertSecret(ctx context.Context, s Secret) error
	GetSecret(ctx context.Context, id string) (Secret, error)
	ListSecrets(ctx context.Context) ([]Secret, error)
	// UpdateSecret replaces key id, nonce and ciphertext (re-encryption).
	UpdateSecret(ctx context.Context, s Secret) error
	DeleteSecret(ctx context.Context, id string) error
	CountSecrets(ctx context.Context) (int, error)
}

// Roles of the open-source edition.
const (
	RoleAdmin  = "admin"
	RoleViewer = "viewer"
)

// User is a control-plane account.
type User struct {
	ID           string
	Username     string
	PasswordHash string
	Role         string
	MFASecretID  string
	MFAEnabled   bool
	MFALastStep  int64
	Disabled     bool
	FailedCount  int
	LockedUntil  time.Time // zero when not locked
	LastLoginAt  time.Time // zero when never
	CreatedAt    time.Time
}

// Users stores accounts and their login-throttling state.
type Users interface {
	CreateUser(ctx context.Context, u User) error
	UserByID(ctx context.Context, id string) (User, error)
	UserByUsername(ctx context.Context, username string) (User, error)
	ListUsers(ctx context.Context) ([]User, error)
	CountUsers(ctx context.Context) (int, error)
	// SetUserPassword also clears the failure counter and any lock.
	SetUserPassword(ctx context.Context, id, hash string) error
	SetUserRole(ctx context.Context, id, role string) error
	SetUserDisabled(ctx context.Context, id string, disabled bool) error
	// SetUserMFA sets (or, with an empty secret id and false, clears) the TOTP secret and resets the replay step.
	SetUserMFA(ctx context.Context, id, secretID string, enabled bool) error
	// AdvanceMFAStep records a used TOTP step; false means it was already used or is older.
	AdvanceMFAStep(ctx context.Context, id string, step int64) (bool, error)
	RecordLoginFailure(ctx context.Context, id string, failed int, lockedUntil time.Time) error
	RecordLoginSuccess(ctx context.Context, id string, at time.Time) error
	UnlockUser(ctx context.Context, id string) error
	DeleteUser(ctx context.Context, id string) error
}

// Session stages: a partial session may only complete MFA.
const (
	StagePasswordOK      = "password_ok"
	StageMFAEnrolRequire = "mfa_enrol_required"
	StageFull            = "full"
)

// Session is a login session; ID is the SHA-256 of the token the client holds.
type Session struct {
	ID            string
	UserID        string
	Stage         string
	CreatedAt     time.Time
	LastSeenAt    time.Time
	ExpiresAt     time.Time
	IP            string
	UserAgent     string
	CSRFTokenHash string
}

// Sessions stores login sessions.
type Sessions interface {
	CreateSession(ctx context.Context, s Session) error
	GetSession(ctx context.Context, id string) (Session, error)
	TouchSession(ctx context.Context, id string, at time.Time) error
	DeleteSession(ctx context.Context, id string) error
	DeleteUserSessions(ctx context.Context, userID string) error
	// DeleteExpiredSessions removes sessions past their absolute expiry or idle since idleBefore.
	DeleteExpiredSessions(ctx context.Context, now, idleBefore time.Time) (int, error)
}

// Token is an API token record; only a hash of the secret is stored.
type Token struct {
	ID         string
	UserID     string
	Name       string
	TokenHash  string
	Scopes     []byte // JSON array
	CIDRs      []byte // JSON array
	ExpiresAt  time.Time
	LastUsedAt time.Time
	CreatedAt  time.Time
}

// Tokens stores API tokens.
type Tokens interface {
	CreateToken(ctx context.Context, t Token) error
	GetToken(ctx context.Context, id string) (Token, error)
	ListTokens(ctx context.Context) ([]Token, error)
	ListTokensByUser(ctx context.Context, userID string) ([]Token, error)
	TouchToken(ctx context.Context, id string, at time.Time) error
	DeleteToken(ctx context.Context, id string) error
}

// AuditEntry is one row of the hash-chained audit log (see internal/audit).
type AuditEntry struct {
	Seq        int64
	ID         string
	At         time.Time
	ActorType  string // user, token, system
	ActorID    string
	IP         string
	Action     string
	ObjectType string
	ObjectID   string
	Details    []byte // JSON text, hashed exactly as stored
	PrevHash   string
	Hash       string
}

// Audit exposes the audit log and its serialising head row.
type Audit interface {
	// BumpAuditHead takes the head row (serialising audit writers until the
	// transaction ends) and returns the next sequence number and the hash of the previous entry.
	BumpAuditHead(ctx context.Context) (seq int64, prevHash string, err error)
	SetAuditHeadHash(ctx context.Context, hash string) error
	AuditHead(ctx context.Context) (seq int64, hash string, err error)
	InsertAudit(ctx context.Context, e AuditEntry) error
	// ListAudit returns entries with seq below beforeSeq (0 means newest), newest first.
	ListAudit(ctx context.Context, beforeSeq int64, limit int) ([]AuditEntry, error)
	// ListAuditAfter returns entries with seq above afterSeq, oldest first (chain verification).
	ListAuditAfter(ctx context.Context, afterSeq int64, limit int) ([]AuditEntry, error)
}

// EventRow is a stored security event: the columns used for filtering plus the
// full JSON document.
type EventRow struct {
	ID       string
	TS       time.Time
	SiteID   string
	Action   string
	Mode     string
	ClientIP string
	Method   string
	Host     string
	Path     string
	Status   int
	RuleIDs  []string
	Body     []byte
	Country  string // ISO 3166-1 alpha-2, "" when unknown
}

// EventFilter narrows ListEvents; zero fields are ignored.
type EventFilter struct {
	SiteID   string
	Action   string
	ClientIP string
	RuleID   string
	From, To time.Time
	Country  string
	Method   string
	Status   int    // 0: any
	Mode     string // detect | block | off
	// Text matches (case-insensitively for path and host) anywhere in the path,
	// host, client address or rule ids. LIKE wildcards in it are literal.
	Text string
}

// Rollup is a per-minute event count.
type Rollup struct {
	Bucket time.Time
	SiteID string
	Action string
	Count  int64
}

// Events stores security events and their per-minute rollups.
type Events interface {
	InsertEvent(ctx context.Context, e EventRow) error
	GetEvent(ctx context.Context, id string) (EventRow, error)
	ListEvents(ctx context.Context, f EventFilter, c Cursor, limit int) ([]EventRow, error)
	CountEvents(ctx context.Context) (int, error)
	DeleteEventsBefore(ctx context.Context, cutoff time.Time, limit int) (int, error)
	// TopEventValues counts events by one dimension (ip, path, country, site, action)
	// inside [f.From, f.To), honouring f.SiteID and f.Action, most frequent first.
	TopEventValues(ctx context.Context, dim string, f EventFilter, limit int) ([]ValueCount, error)
	// CountEventsByEndpoint counts one site's events that carry ruleID, grouped
	// by method and concrete request path, busiest first.
	CountEventsByEndpoint(ctx context.Context, siteID, ruleID string, from, to time.Time, limit int) ([]EndpointCount, error)
	AddRollup(ctx context.Context, r Rollup) error
	ListRollups(ctx context.Context, from, to time.Time) ([]Rollup, error)
	DeleteRollupsBefore(ctx context.Context, cutoff time.Time) (int, error)
}

// Certificate is an uploaded certificate chain. The private key is an encrypted
// secret (KeySecretID); only the public material is kept here.
type Certificate struct {
	ID          string
	Name        string
	Hosts       []string
	NotBefore   time.Time
	NotAfter    time.Time
	Issuer      string
	Fingerprint string // hex SHA-256 of the leaf certificate
	ChainPEM    string
	KeySecretID string
	CreatedAt   time.Time
}

// Certificates stores uploaded certificates.
type Certificates interface {
	InsertCertificate(ctx context.Context, c Certificate) error
	GetCertificate(ctx context.Context, id string) (Certificate, error)
	ListCertificates(ctx context.Context) ([]Certificate, error)
	DeleteCertificate(ctx context.Context, id string) error
}

// BlockPage is a custom block page template (html/template source).
type BlockPage struct {
	ID        string
	HTML      string
	UpdatedAt time.Time
}

// BlockPages stores block page templates.
type BlockPages interface {
	// PutBlockPage creates or replaces the template with p.ID.
	PutBlockPage(ctx context.Context, p BlockPage) error
	GetBlockPage(ctx context.Context, id string) (BlockPage, error)
	ListBlockPages(ctx context.Context) ([]BlockPage, error)
	DeleteBlockPage(ctx context.Context, id string) error
}

// OpenAPIDoc is an uploaded OpenAPI document, kept verbatim.
type OpenAPIDoc struct {
	ID        string
	Name      string
	Version   string // 3.0 or 3.1
	SHA256    string // hex digest of Body
	Body      string
	UpdatedAt time.Time
}

// CABundle is an uploaded set of CA certificates that verify client certificates.
type CABundle struct {
	ID          string
	Name        string
	Subjects    []string
	Fingerprint string // hex SHA-256 over the DER of every certificate
	PEM         string
	NotAfter    time.Time // earliest expiry in the bundle
	CreatedAt   time.Time
}

// APIAssets stores OpenAPI documents and client-certificate CA bundles.
type APIAssets interface {
	// PutOpenAPIDoc creates or replaces the document with d.ID.
	PutOpenAPIDoc(ctx context.Context, d OpenAPIDoc) error
	GetOpenAPIDoc(ctx context.Context, id string) (OpenAPIDoc, error)
	ListOpenAPIDocs(ctx context.Context) ([]OpenAPIDoc, error)
	DeleteOpenAPIDoc(ctx context.Context, id string) error

	InsertCABundle(ctx context.Context, b CABundle) error
	GetCABundle(ctx context.Context, id string) (CABundle, error)
	ListCABundles(ctx context.Context) ([]CABundle, error)
	DeleteCABundle(ctx context.Context, id string) error
}

// Ban sources.
const (
	BanManual   = "manual"
	BanAuto     = "auto"
	BanCrowdSec = "crowdsec"
)

// Ban is a stored temporary ban. SiteID "" applies to every site.
type Ban struct {
	ID        string
	IP        string
	SiteID    string
	Source    string
	Reason    string
	CreatedBy string
	CreatedAt time.Time
	Until     time.Time
}

// Bans stores temporary bans.
type Bans interface {
	// PutBan inserts a ban, replacing an existing one for the same address and site.
	PutBan(ctx context.Context, b Ban) error
	GetBan(ctx context.Context, id string) (Ban, error)
	// ListActiveBans returns bans that have not expired at now, soonest to expire first.
	ListActiveBans(ctx context.Context, now time.Time) ([]Ban, error)
	DeleteBan(ctx context.Context, id string) error
	DeleteExpiredBans(ctx context.Context, now time.Time) (int, error)
}

// EndpointCount is one row of CountEventsByEndpoint.
type EndpointCount struct {
	Method string
	Path   string
	Count  int64
}

// ValueCount is one row of a top-N listing.
type ValueCount struct {
	Value string
	Count int64
}

// Top-N dimensions understood by TopEventValues.
const (
	DimIP      = "ip"
	DimPath    = "path"
	DimCountry = "country"
	DimSite    = "site"
	DimAction  = "action"
)
